<script setup>
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'; import {router} from '@inertiajs/vue3'; import axios from 'axios'; import { HugeiconsIcon } from '@hugeicons/vue'; import { CheckmarkCircle02Icon, CrownIcon, HelpCircleIcon, UserAdd01Icon } from '@hugeicons/core-free-icons'; import AppLayout from '@/Layouts/AppLayout.vue'; import PrimaryButton from '@/Components/PrimaryButton.vue';
const props=defineProps({initialState:Object,categories:Array}); const state=ref(props.initialState); const answer=reactive({text:'',animal:'',object:'',celebrity:'',place:'',capital:'',job:''}); const petitBacGrading=reactive({animal:false,object:false,celebrity:false,place:false,capital:false,job:false}); const remaining=ref(0); const sentFor=ref(null); let poller,ticker;
const room=computed(()=>state.value.room); const status=computed(()=>room.value.status); const current=computed(()=>state.value.question); const isHost=computed(()=>state.value.isHost);
const selected=ref(room.value.categories.length ? room.value.categories.map(c=>c.id) : props.categories.map(c=>c.id)); const total=ref(room.value.questions_total); const seconds=ref(room.value.seconds_per_question);
const refresh=async()=>{state.value=(await axios.get(route('culture-quiz.rooms.state',room.value.public_id))).data};
const submitAnswer=async()=>{if(sentFor.value===current.value?.position||status.value!=='answering')return; sentFor.value=current.value.position; const payload=current.value.type==='petit_bac'?Object.fromEntries(current.value.fields.map(f=>[f,answer[f]])):{text:answer.text}; await axios.post(route('culture-quiz.rooms.answer',room.value.public_id),{answer:payload});};
const updateTimer=()=>{if(!room.value.question_ends_at)return; remaining.value=Math.max(0,Math.ceil((new Date(room.value.question_ends_at)-Date.now())/1000)); if(remaining.value===0)submitAnswer();};
watch(()=>current.value?.position,()=>{Object.keys(answer).forEach(k=>answer[k]='');sentFor.value=null;updateTimer()});
watch(()=>state.value.review?.id,()=>Object.keys(petitBacGrading).forEach(k=>petitBacGrading[k]=false));
const save=()=>axios.patch(route('culture-quiz.rooms.update',room.value.public_id),{questions_total:total.value,seconds_per_question:seconds.value,category_ids:selected.value}).then(refresh);
const start=async()=>{await axios.patch(route('culture-quiz.rooms.update',room.value.public_id),{questions_total:total.value,seconds_per_question:seconds.value,category_ids:selected.value});router.post(route('culture-quiz.rooms.start',room.value.public_id));};
const judge=async payload=>{await axios.post(route('culture-quiz.rooms.answers.judge',[room.value.public_id,state.value.review.id]),payload);await refresh()};
const vote=async accepted=>{await axios.post(route('culture-quiz.rooms.answers.vote',[room.value.public_id,state.value.review.id]),{accepted});await refresh()};
const copy=()=>navigator.clipboard.writeText(location.href);
onMounted(()=>{poller=setInterval(refresh,1000);ticker=setInterval(updateTimer,250);updateTimer()}); onUnmounted(()=>{clearInterval(poller);clearInterval(ticker)});
</script>
<template><AppLayout title="Culture Quiz"><main class="qp-shell py-8"><section class="flex flex-wrap items-center justify-between gap-4 rounded-3xl bg-cyan-700 p-6 text-white"><div><div class="text-xs font-black uppercase text-cyan-200">Salon {{room.code}}</div><h1 class="text-3xl font-black">Culture Quiz</h1></div><button v-if="status==='lobby'" class="rounded-xl bg-white/15 px-4 py-2 font-bold" @click="copy">Copier l’invitation</button></section>
<section v-if="status==='lobby'" class="mt-7 grid gap-6 lg:grid-cols-[1fr_.7fr]"><div class="qp-card"><h2 class="text-2xl font-black">Joueurs</h2><div class="mt-4 space-y-2"><div v-for="p in room.players" :key="p.id" class="flex items-center gap-2 rounded-xl bg-violet-50 p-3 font-bold dark:bg-white/5">{{p.user.name}} <HugeiconsIcon v-if="p.user_id===room.host_id" :icon="CrownIcon" :size="18" class="text-amber-500" aria-label="Hôte" /></div></div><button v-if="!state.isPlayer" class="mt-5 rounded-xl bg-violet-600 px-5 py-3 font-black text-white" @click="router.post(route('culture-quiz.rooms.join',room.public_id))">Rejoindre</button><div v-if="isHost&&state.invitableFriends.length" class="mt-6 border-t pt-5"><b>Inviter un ami</b><div class="mt-2 flex flex-wrap gap-2"><button v-for="friend in state.invitableFriends" :key="friend.id" class="inline-flex items-center gap-2 rounded-xl bg-cyan-100 px-3 py-2 text-sm font-bold text-cyan-800" @click="router.post(route('culture-quiz.rooms.invite',room.public_id),{friend_id:friend.id})"><HugeiconsIcon :icon="UserAdd01Icon" :size="17" />{{friend.name}}</button></div></div></div><div v-if="isHost" class="qp-card space-y-5"><h2 class="text-2xl font-black">Réglages</h2><label class="block font-bold">Questions <input v-model.number="total" type="number" min="1" max="50" class="mt-1 w-full rounded-xl border-slate-300 bg-white text-slate-900 dark:border-white/15 dark:bg-slate-950 dark:text-white"></label><label class="block font-bold">Secondes par question <input v-model.number="seconds" type="number" min="5" max="180" class="mt-1 w-full rounded-xl border-slate-300 bg-white text-slate-900 dark:border-white/15 dark:bg-slate-950 dark:text-white"></label><div><div class="flex items-center justify-between"><b>Thèmes</b><span class="text-xs font-black text-slate-400">{{selected.length}} sélectionné(s)</span></div><div class="mt-3 grid gap-3 sm:grid-cols-2"><label v-for="cat in categories" :key="cat.id" class="group relative flex cursor-pointer items-center gap-3 rounded-2xl border-2 p-4 transition" :class="selected.includes(cat.id) ? 'border-cyan-500 bg-cyan-50 shadow-sm dark:bg-cyan-500/10' : 'border-slate-200 bg-white hover:border-cyan-300 dark:border-white/10 dark:bg-white/5'"><input v-model="selected" type="checkbox" :value="cat.id" class="sr-only"><span class="flex size-10 shrink-0 items-center justify-center rounded-xl transition" :class="selected.includes(cat.id) ? 'bg-cyan-500 text-white' : 'bg-slate-100 text-slate-400 dark:bg-white/10'"><HugeiconsIcon :icon="selected.includes(cat.id) ? CheckmarkCircle02Icon : HelpCircleIcon" :size="21" /></span><span class="min-w-0"><span class="block truncate font-black text-slate-900 dark:text-white">{{cat.name}}</span><span class="mt-0.5 block text-xs font-bold text-slate-400">{{cat.questions_count}} question(s)</span></span></label></div><p v-if="!categories.length" class="mt-3 rounded-2xl border-2 border-dashed border-slate-200 p-5 text-center text-sm font-bold text-slate-400 dark:border-white/10">Aucun thème disponible.</p></div><PrimaryButton @click="save">Enregistrer</PrimaryButton><button class="w-full rounded-2xl bg-cyan-600 p-4 font-black text-white" @click="start">Lancer la partie</button></div></section>
<section v-else-if="status==='answering'&&current" class="qp-card mx-auto mt-8 max-w-4xl text-center"><div class="flex items-center justify-between font-black text-cyan-600"><span>Question {{current.position}} / {{room.questions_total}}</span><div class="relative size-16" role="timer" :aria-label="`${remaining} secondes restantes`"><svg class="size-16 -rotate-90" viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="27" fill="none" stroke="currentColor" stroke-width="6" class="text-slate-200 dark:text-white/10"/><circle cx="32" cy="32" r="27" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" class="text-cyan-500 transition-[stroke-dashoffset] duration-300" :stroke-dasharray="2*Math.PI*27" :stroke-dashoffset="2*Math.PI*27*(1-Math.min(1,remaining/room.seconds_per_question))"/></svg><span class="absolute inset-0 flex items-center justify-center text-lg font-black text-cyan-700 dark:text-cyan-300">{{remaining}}</span></div></div><img v-if="current.image_url" :src="current.image_url" class="mx-auto mt-6 max-h-72 rounded-2xl"><template v-if="current.type==='petit_bac'"><div class="qp-kicker mt-8">Petit bac · lettre</div><div class="mt-2 text-7xl font-black uppercase text-violet-600">{{current.letter?.toUpperCase()}}</div><div class="mt-7 grid gap-3 sm:grid-cols-2"><label v-for="field in current.fields" :key="field" class="text-left text-sm font-black capitalize">{{field}}<input v-model="answer[field]" class="mt-1 w-full rounded-xl border-slate-300 bg-white text-slate-900 placeholder:text-slate-400 dark:border-white/15 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-500" :placeholder="`${field} en ${current.letter?.toUpperCase()}`"></label></div></template><template v-else><h2 class="mx-auto mt-10 max-w-2xl text-3xl font-black">{{current.question}}</h2><textarea v-model="answer.text" rows="4" class="mt-8 w-full rounded-2xl border-slate-300 bg-white text-lg text-slate-900 placeholder:text-slate-400 dark:border-white/15 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-500" placeholder="Votre réponse…"/></template><p class="qp-muted mt-5">La réponse est envoyée automatiquement à la fin du temps.</p></section>
<section v-else-if="status==='reviewing'" class="qp-card mx-auto mt-8 max-w-3xl"><h2 class="text-3xl font-black">Validation des réponses</h2><div v-if="state.review" class="mt-6 space-y-6"><div class="rounded-2xl bg-cyan-50 p-6 dark:bg-cyan-500/10"><template v-if="state.review.type==='petit_bac'"><div class="qp-kicker">Petit Bac · lettre</div><div class="mt-2 text-6xl font-black uppercase text-violet-600">{{state.review.letter}}</div></template><template v-else><div class="qp-kicker">Question</div><h3 class="mt-2 text-2xl font-black">{{state.review.question}}</h3><div class="mt-5 border-t border-cyan-200 pt-4 dark:border-cyan-400/20"><div class="text-xs font-black uppercase tracking-wider text-cyan-700 dark:text-cyan-300">Réponse attendue</div><p class="mt-1 text-xl font-black">{{state.review.expected_answer||'—'}}</p></div></template></div><div class="rounded-2xl bg-violet-50 p-6 dark:bg-white/5"><div class="qp-kicker">Réponse de {{state.review.player.name}}</div><template v-if="state.review.type==='petit_bac'"><div class="mt-5 space-y-3"><div v-for="field in state.review.fields" :key="field" class="grid items-center gap-3 rounded-xl bg-white p-4 dark:bg-slate-950 sm:grid-cols-[1fr_1.5fr_auto]"><span class="font-black capitalize">{{field}}</span><span class="min-w-0 break-words text-lg font-bold">{{state.review.answer[field]||'—'}}</span><div v-if="isHost" class="flex gap-2"><button class="rounded-lg px-3 py-2 text-sm font-black" :class="petitBacGrading[field] ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-500 dark:bg-white/10'" @click="petitBacGrading[field]=true">Valider</button><button class="rounded-lg px-3 py-2 text-sm font-black" :class="!petitBacGrading[field] ? 'bg-rose-600 text-white' : 'bg-slate-100 text-slate-500 dark:bg-white/10'" @click="petitBacGrading[field]=false">Refuser</button></div></div></div><div v-if="isHost" class="mt-5 flex items-center justify-between border-t pt-5"><b>{{Object.values(petitBacGrading).filter(Boolean).length*0.5}} point(s)</b><button class="rounded-xl bg-violet-600 px-5 py-3 font-black text-white" @click="judge({categories:{...petitBacGrading}})">Confirmer la correction</button></div></template><template v-else><p class="mt-3 whitespace-pre-wrap text-xl font-black">{{state.review.answer.text||'—'}}</p><div v-if="isHost" class="mt-6 flex flex-wrap gap-3"><button class="rounded-xl bg-emerald-600 px-5 py-3 font-black text-white" @click="judge({correct:true})">Correcte</button><button class="rounded-xl bg-rose-600 px-5 py-3 font-black text-white" @click="judge({correct:false})">Incorrecte</button><button class="rounded-xl bg-violet-600 px-5 py-3 font-black text-white" @click="axios.post(route('culture-quiz.rooms.answers.poll',[room.public_id,state.review.id])).then(refresh)">Lancer un sondage</button></div></template><div v-if="state.review.poll_open" class="mt-6 border-t pt-5"><p class="font-black">Sondage : oui {{state.review.yes}} · non {{state.review.no}}</p><div v-if="!state.review.voted&&!isHost" class="mt-3 flex gap-2"><button class="rounded-xl bg-emerald-600 px-5 py-2 font-bold text-white" @click="vote(true)">Oui</button><button class="rounded-xl bg-rose-600 px-5 py-2 font-bold text-white" @click="vote(false)">Non</button></div></div></div></div><p v-else>Finalisation…</p></section>
<section v-else-if="status==='finished'" class="qp-card mx-auto mt-8 max-w-3xl text-center"><div class="qp-kicker">Partie terminée</div><h2 class="mt-2 text-4xl font-black">Classement final</h2><div class="mt-7 space-y-3"><div v-for="(p,i) in [...room.players].sort((a,b)=>b.score-a.score)" :key="p.id" class="flex justify-between rounded-2xl bg-violet-50 p-4 text-xl font-black dark:bg-white/5"><span>{{i+1}}. {{p.user.name}}</span><span>{{p.score}} pts</span></div></div></section></main></AppLayout></template>
